import{_ as s,o as a,c as i,ae as t}from"./chunks/framework.B2ul6ABY.js";const k=JSON.parse('{"title":"Operations","description":"","frontmatter":{},"headers":[],"relativePath":"runbook/operations.md","filePath":"runbook/operations.md"}'),n={name:"runbook/operations.md"};function o(r,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h1><p>Use this page for day-to-day Saivage operation. Incident recovery lives in <a href="./incidents.html">Incidents</a>; release validation lives in <a href="./release.html">Release</a>.</p><h2 id="startup-modes" tabindex="-1">Startup modes <a class="header-anchor" href="#startup-modes" aria-label="Permalink to &quot;Startup modes&quot;">​</a></h2><h3 id="api-server-only" tabindex="-1">API/server only <a class="header-anchor" href="#api-server-only" aria-label="Permalink to &quot;API/server only&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span></span></code></pre></div><p>This starts Fastify, public docs/SPA serving, auth-protected API routes, <code>/ws</code>, MCP startup, and optional Telegram startup. It does <strong>not</strong> create an <code>ActiveRuntime</code> dispatch loop.</p><h3 id="server-with-runtime-creation" tabindex="-1">Server with runtime creation <a class="header-anchor" href="#server-with-runtime-creation" aria-label="Permalink to &quot;Server with runtime creation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/src/server/server.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-runtime</span></span></code></pre></div><p>With <code>--create-runtime</code>, Saivage initializes <code>ActiveRuntime</code>, reads or creates runtime state, runs startup repair/settle behavior, and can dispatch queued work. The CLI start path exposes the same flag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SAIVAGE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./bin/saivage.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-runtime</span></span></code></pre></div><p>Use <code>--create-runtime</code> when the operator intends this process to own dispatch. Use server-only mode for read-only inspection/control setups where persisted-state controls are enough.</p><h2 id="lxc-systemd-units" tabindex="-1">LXC/systemd units <a class="header-anchor" href="#lxc-systemd-units" aria-label="Permalink to &quot;LXC/systemd units&quot;">​</a></h2><p>The LXC deployments use these unit names:</p><ul><li><code>saivage.service</code> — default Saivage v3 service.</li><li><code>saivage-v3-target.service</code> — target workspace service.</li></ul><p>Common checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saivage.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saivage.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saivage-v3-target.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saivage-v3-target.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>See <a href="./lxc-operations.html">LXC operations</a> for deployment-specific restart and log guidance.</p><h2 id="public-and-protected-surfaces" tabindex="-1">Public and protected surfaces <a class="header-anchor" href="#public-and-protected-surfaces" aria-label="Permalink to &quot;Public and protected surfaces&quot;">​</a></h2><p>Public when the server is up:</p><ul><li><code>GET /health</code></li><li><code>/</code> Web Control Room assets</li><li><code>/docs/</code> built VitePress docs</li></ul><p>Protected when <code>SAIVAGE_API_TOKEN</code> is configured:</p><ul><li>all <code>/api/*</code></li><li><code>/ws</code></li></ul><p>Accepted auth methods:</p><ul><li><code>Authorization: Bearer &lt;token&gt;</code></li><li><code>?token=&lt;token&gt;</code></li></ul><p>If no API token is configured, tokenless startup is only allowed on localhost-style bindings.</p><h2 id="health-and-state-contracts" tabindex="-1">Health and state contracts <a class="header-anchor" href="#health-and-state-contracts" aria-label="Permalink to &quot;Health and state contracts&quot;">​</a></h2><h3 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/health</span></span></code></pre></div><p>Expected status: <code>200</code>.</p><p>Expected top-level JSON keys: <code>status</code>, <code>version</code>, <code>project</code>, <code>runtime</code>.</p><p><code>runtime</code> is <code>unknown</code>, <code>idle</code>, <code>running</code>, <code>paused</code>, <code>error</code>, or <code>frozen</code>. When the runtime is frozen and a freeze manifest is present, the response can also include <code>frozen_reason</code>.</p><h3 id="runtime-state" tabindex="-1">Runtime state <a class="header-anchor" href="#runtime-state" aria-label="Permalink to &quot;Runtime state&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/state</span></span></code></pre></div><p>Expected status: <code>200</code>.</p><p>Expected top-level JSON keys: <code>runtime</code>, <code>cardIndex</code>.</p><p><code>runtime</code> is the current <code>RuntimeState</code> or <code>null</code> when no runtime state exists. <code>cardIndex</code> includes <code>total</code>, <code>byStatus</code>, and <code>byType</code>.</p><h3 id="compact-runtime-status" tabindex="-1">Compact runtime status <a class="header-anchor" href="#compact-runtime-status" aria-label="Permalink to &quot;Compact runtime status&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/runtime/status</span></span></code></pre></div><p>This returns <code>runtime</code>, <code>paused</code>, <code>currentCardId</code>, and <code>goalCount</code> and falls back to persisted state if no live <code>ActiveRuntime</code> is attached.</p><h2 id="runtime-control-contracts" tabindex="-1">Runtime control contracts <a class="header-anchor" href="#runtime-control-contracts" aria-label="Permalink to &quot;Runtime control contracts&quot;">​</a></h2><p>Pause/resume validation is shared across REST endpoints, CLI commands, web UI controls, and analyst tools. Server-hosted analyst chat/WebSocket controls receive the live <code>ActiveRuntime</code> when the server was started with <code>--create-runtime</code>; direct utility use without a live runtime falls back to canonical persisted-state control and records that only disk state changed.</p><h3 id="pause" tabindex="-1">Pause <a class="header-anchor" href="#pause" aria-label="Permalink to &quot;Pause&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/pause</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Expected status: <code>200</code>.</p><p>Expected top-level JSON keys: <code>status</code>, <code>project_id</code>, <code>pid</code>, <code>started_at</code>, <code>paused</code>, <code>queue</code>, <code>running_processes</code>, <code>updated_at</code>.</p><p>Pause stops new dispatch. Running processes are not forcibly killed by pause alone. The response body is the updated <code>RuntimeState</code>.</p><h3 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Expected status: <code>200</code>.</p><p>Expected top-level JSON keys: <code>status</code>, <code>project_id</code>, <code>pid</code>, <code>started_at</code>, <code>paused</code>, <code>queue</code>, <code>running_processes</code>, <code>updated_at</code>.</p><p>Resume re-enables dispatch. Depending on queued work, the runtime may settle into <code>idle</code> or continue in <code>running</code>. The response body is the updated <code>RuntimeState</code>.</p><h3 id="freeze" tabindex="-1">Freeze <a class="header-anchor" href="#freeze" aria-label="Permalink to &quot;Freeze&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/freeze</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;reason&quot;:&quot;operator handoff before maintenance&quot;}&#39;</span></span></code></pre></div><p>Freeze is an intentional operator handoff. Saivage records a freeze manifest and moves runtime state to <code>frozen</code> with pause semantics.</p><h3 id="resume-from-freeze" tabindex="-1">Resume from freeze <a class="header-anchor" href="#resume-from-freeze" aria-label="Permalink to &quot;Resume from freeze&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/resume-from-freeze</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>If a freeze manifest exists, Saivage restores queued work, clears the manifest, and returns the restored queue and current-card reference. Do not use generic resume from <code>frozen</code> or <code>error</code> states.</p><h2 id="directives-instead-of-legacy-dispatch" tabindex="-1">Directives instead of legacy dispatch <a class="header-anchor" href="#directives-instead-of-legacy-dispatch" aria-label="Permalink to &quot;Directives instead of legacy dispatch&quot;">​</a></h2><p>Legacy explicit dispatch endpoints are not part of the current operator API. Start or correct work by recording directives:</p><ul><li><code>POST /api/runtime/lets_dance</code> records a project kickoff directive.</li><li><code>POST /api/runtime/goals/:id/needs_corrections</code> records goal corrections.</li><li><code>POST /api/runtime/project/needs_corrections</code> records project-level corrections.</li></ul><p>The runtime consumes eligible directives on scheduler safe ticks and owns subsequent card activation.</p><h2 id="analyst-chat-websocket" tabindex="-1">Analyst chat WebSocket <a class="header-anchor" href="#analyst-chat-websocket" aria-label="Permalink to &quot;Analyst chat WebSocket&quot;">​</a></h2><p>The analyst chat WebSocket endpoint is <code>/ws</code>.</p><p>Auth is the same as protected API routes:</p><ul><li><code>ws://localhost:8080/ws?token=&lt;token&gt;</code></li><li>or an <code>Authorization: Bearer &lt;token&gt;</code> header from clients that can set WebSocket headers.</li></ul><p>Example with query-token auth:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">websocat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ws://localhost:8080/ws?token=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Messages are serialized per connection. The server preserves sanitization and either processes turns in send order or rejects overlap according to the analyst WebSocket contract.</p><h2 id="evidence-files-and-safe-process-views" tabindex="-1">Evidence, files, and safe process views <a class="header-anchor" href="#evidence-files-and-safe-process-views" aria-label="Permalink to &quot;Evidence, files, and safe process views&quot;">​</a></h2><p><code>GET /api/cards/:id</code> returns card detail plus an <code>evidence</code> object with generated files, verification commands, artifact paths, tool errors, and optional parse-failure information. Generated-file enrichment is a detail-route behavior, not a list-route behavior.</p><p><code>GET /api/files</code> lists contained directories and files. <code>GET /api/files/content?path=...</code> returns text previews only inside the project boundary and subject to secret blocking/redaction, size limits, and binary rejection.</p><p><code>GET /api/processes</code> and <code>GET /api/processes/:id</code> expose safe redacted process views instead of raw process-registry records.</p><h2 id="backup-and-maintenance" tabindex="-1">Backup and maintenance <a class="header-anchor" href="#backup-and-maintenance" aria-label="Permalink to &quot;Backup and maintenance&quot;">​</a></h2><p>Persistent state lives primarily in <code>.saivage/</code>. Generated and temporary work outputs live in <code>.saivage-work/</code>.</p><p>Recommended maintenance sequence:</p><ol><li>Pause or freeze the runtime.</li><li>Confirm <code>/health</code>, <code>/api/state</code>, and the queue/current-card state.</li><li>Back up <code>.saivage/</code>.</li><li>Back up <code>.saivage-work/</code> if process logs or generated artifacts are needed.</li><li>Resume or <code>resume-from-freeze</code> when the maintenance window ends.</li></ol>`,76)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
